class Solution {
public:
    int maxSumAfterPartitioning(vector<int>& arr, int k) {
        int n = arr.size();
        vector<long long> dp(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            long long mx = 0;
            for (int j = 1; j <= k && i - j >= 0; j++) {
                mx = max(mx, (long long)arr[i - j]);
                dp[i] = max(dp[i], dp[i - j] + mx * j);
            }
        }
        return (int)dp[n];
    }
};
